import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with valid customer, date, and lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  assert.equal(result.ok, true);
  assert.deepEqual(result.value, {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 2,
        unitPrice: 8500,
        vatRate: 21,
      },
    ],
  });
});

test('createInvoice handles multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 1 },
      { sku: 'HOST-MONTH', qty: 12 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 3);
  assert.deepEqual(result.value.lines[0], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 3,
    unitPrice: 8500,
    vatRate: 21,
  });
  assert.deepEqual(result.value.lines[1], {
    sku: 'ICON-SET',
    name: 'Icon set (24 icons)',
    qty: 1,
    unitPrice: 980,
    vatRate: 21,
  });
  assert.deepEqual(result.value.lines[2], {
    sku: 'HOST-MONTH',
    name: 'Website hosting (month)',
    qty: 12,
    unitPrice: 1500,
    vatRate: 21,
  });
});

test('createInvoice returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

