    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'STICKER', qty: 100, unitPrice: 50, name: 'Sticker sheet', vatRate: 21 },
      { sku: 'LOGO-PACK', qty: 1, unitPrice: 120000, name: 'Logo package', vatRate: 21 },
      { sku: 'PHOTO-LIC', qty: 5, unitPrice: 996, name: 'Stock photo licence', vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const expected = 100 * 50 + 1 * 120000 + 5 * 996;
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, expected);
});

test('invoiceTotals calculates discount for single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 2, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 10 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 1700);
  assert.equal(totals.total, 15300);
});

test('invoiceTotals sums discounts across multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 2, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 10 },
      { sku: 'ICON-SET', qty: 2, unitPrice: 980, name: 'Icon set (24 icons)', vatRate: 21, discountPercent: 20 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 17000 + 1960);
  assert.equal(totals.discount, 1700 + 392);
  assert.equal(totals.total, 18960 - 2092);
});

test('invoiceTotals with 100% discount clamps to zero', () => {
