    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 2, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 100 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 17000);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with discount less than subtotal', () => {
  const invoice = {
