    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 1, unitPrice: 1000, name: 'Design work (hour)', vatRate: 21, discountPercent: 30 },
      { sku: 'ICON-SET', qty: 1, unitPrice: 500, name: 'Icon set (24 icons)', vatRate: 21, discountPercent: 50 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1500);
  assert.equal(totals.discount, 300 + 250);
  assert.equal(totals.total, 950);
});

test('addLine adds a new line to an invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const result = addLine(invoice, { sku: 'ICON-SET', qty: 1 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.deepEqual(result.value.lines[1], {
    sku: 'ICON-SET',
    name: 'Icon set (24 icons)',
    qty: 1,
    unitPrice: 980,
    vatRate: 21,
  });
});

test('addLine increases qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].qty, 5);
});

test('addLine with multiple existing lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'ICON-SET', qty: 1 },
    ],
  }).value;

  const result = addLine(invoice, { sku: 'ICON-SET', qty: 2 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].qty, 2);
  assert.equal(result.value.lines[1].qty, 3);
});

test('addLine returns NOT_DRAFT if invoice is not draft', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 2, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const result = addLine(invoice, { sku: 'ICON-SET', qty: 1 });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('addLine returns QTY_INVALID for invalid quantity', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
