    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const result = addLine(invoice, { sku: 'UNKNOWN', qty: 1 });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('addLine does not mutate original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const originalLines = JSON.stringify(invoice.lines);

  addLine(invoice, { sku: 'ICON-SET', qty: 1 });

  assert.equal(JSON.stringify(invoice.lines), originalLines);
  assert.equal(invoice.lines.length, 1);
});

test('addLine accepts discountPercent for new line', () => {
