  assert.equal(result.ok, false);
  assert.equal(result.error, 'DISCOUNT_INVALID');
});

test('removeLine removes a line from an invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'ICON-SET', qty: 1 },
    ],
  }).value;

  const result = removeLine(invoice, 'DES-HOUR');

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'ICON-SET');
});

test('removeLine preserves other lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'ICON-SET', qty: 1 },
      { sku: 'HOST-MONTH', qty: 12 },
    ],
  }).value;

  const result = removeLine(invoice, 'ICON-SET');

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[1].sku, 'HOST-MONTH');
});

test('removeLine returns LINE_NOT_FOUND for unknown SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const result = removeLine(invoice, 'UNKNOWN');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'LINE_NOT_FOUND');
});

test('removeLine returns NO_LINES when removing the last line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const result = removeLine(invoice, 'DES-HOUR');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('removeLine returns NOT_DRAFT if invoice is not draft', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 2, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const result = removeLine(invoice, 'DES-HOUR');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('removeLine does not mutate original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'ICON-SET', qty: 1 },
    ],
  }).value;

  const originalLines = JSON.stringify(invoice.lines);

  removeLine(invoice, 'ICON-SET');

  assert.equal(JSON.stringify(invoice.lines), originalLines);
  assert.equal(invoice.lines.length, 2);
});

